     9	/**
    10	 * How one kind of document reads. The steps are the same for every kind and written here once; each kind
    11	 * gives its title and language, who the document is for, and what it adds at the end.
    12	 */
    13	abstract class DocumentLayout {
    14	
    15	    private final String title;
    16	    private final DocumentLanguage language;
    17	
    18	    DocumentLayout(String title, DocumentLanguage language) {
    19	        this.title = title;
    20	        this.language = language;
    21	    }
    22	
    23	    /** The layout of the document a guest identified this way gets. */
    24	    static DocumentLayout forGuest(Identification identification) {
    25	        return switch (identification) {
    26	            case Identification.Cpf cpf -> new ReceiptLayout();
    27	            case Identification.Company company -> new InvoiceLayout();
    28	            case Identification.Passport passport -> new BookingReceiptLayout();
    29	        };
    30	    }
    31	
    32	    String title() {
    33	        return title;
    34	    }
    35	
    36	    /** The lines, each ending in a line break, that say who the document is for. */
    37	    abstract String guestLines(Reservation reservation);
    38	
    39	    /** The lines, each ending in a line break, that come after the total. */
    40	    String closingLines(Reservation reservation) {
    41	        return "";
    42	    }
    43	
    44	    final String money(BigDecimal amount) {
    45	        return language.money(amount);
    46	    }
    47	
    48	    final String text(Reservation reservation, Room room) {
    49	        Price price = reservation.price();
    50	        StringBuilder text = new StringBuilder();
    51	        text.append(title).append(' ').append(language.number).append(' ').append(reservation.id()).append('\n');
    52	        text.append(guestLines(reservation));
    53	        text.append(language.room).append(": ").append(room.number()).append(" (").append(room.type()).append(")\n");
    54	        text.append(language.checkIn).append(": ").append(language.date(reservation.checkIn()))
    55	                .append(" | ").append(language.checkOut).append(": ").append(language.date(reservation.checkOut()))
    56	                .append(" | ").append(price.nights()).append(price.nights() == 1 ? language.night : language.nights)
    57	                .append('\n');
    58	        text.append(language.subtotal).append(": ").append(language.money(price.subtotal())).append('\n');
    59	        if (price.discount().signum() > 0) {
    60	            text.append(language.discount).append(": ").append(language.money(price.discount())).append('\n');
    61	        }
    62	        text.append(language.total).append(": ").append(language.money(price.total())).append('\n');
    63	        text.append(closingLines(reservation));
    64	        return text.toString();
    65	    }
    66	
    67	    final String guestName(Reservation reservation) {
    68	        return language.guest + ": " + reservation.guest().name();
    69	    }
