 6	    private static Identification readIdentification(ResultSet row) throws SQLException {
 7	        if (row.getString("company_cnpj") != null) {
 8	            return new Identification.Company(row.getString("company_cnpj"), row.getString("company_name"));
 9	        }
10	        if (row.getString("guest_passport") != null) {
11	            return new Identification.Passport(row.getString("guest_passport"), row.getString("guest_country"));
12	        }
13	        return new Identification.Cpf(row.getString("guest_cpf"));
14	    }
15	
16	private static Reservation read(ResultSet row) throws SQLException {
17	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), readIdentification(row));
18	        NewReservation request = new NewReservation(
19	                row.getInt("room_number"),
